    "title": "USB micro-B receptacle (generic)",
    "blurb": "the \"network of offsets\" torture test",
    "source": "# USB micro-B receptacle (generic) — the \"network of offsets\" torture test.\n#\n# Signal pads, shield legs, locating pegs (NPTH), and through-slots, each\n# dimensioned from something different in the datasheet: the pegs from pin 1,\n# the shield slots from the pegs, the front tabs by outer-to-outer span about\n# the centerline. Every number below is entered exactly as the drawing gives\n# it. (Dimensions are illustrative, not a specific vendor's.)\n\nunits mm\n\nfootprint \"USB-MICRO-B\" {\n  description \"USB micro-B receptacle, SMD signals + through-hole shield\"\n  refdes \"J\"\n  tags usb, connector\n\n  let e  = 0.65        # signal pitch          (drawing callout \"e\")\n  let C1 = 2.89        # peg to pin-1 center, x        (\"C1\")\n  let C2 = 0.55        # peg below pin-row centers, y  (\"C2\")\n\n  # --- signal pads ------------------------------------------------------\n  default pad rect 0.4 x 1.35\n  row sig pads 1..5 pitch e going right\n  pad 3 at (0, 0)                          # anchor the row: D+ pin on the origin\n\n  # --- locating pegs (NPTH) --------------------------------------------\n  hole PEG1 0.85\n  hole PEG1 is C1 left of pad 1 and C2 below pad 1\n  hole PEG2 mirrors hole PEG1 across y     # symmetric about the centerline\n\n  # --- shield legs: plated through-slots, dimensioned off the pegs ------\n  pad \"SH1\" tht oval 1.2 x 1.9 drill slot 0.6 x 1.3\n  pad \"SH1\" is 1.05 left of hole PEG1 and 0.25 above hole PEG1\n  pad \"SH2\" mirrors pad \"SH1\" across y\n\n  # --- front shell tabs: L-shaped SMD pads, placed by span + symmetry ---\n  pad \"SH3\" polygon (0, 0) (1.05, 0) (1.05, 1.45) (0.6, 1.45) (0.6, 2.2) (0, 2.2)\n  pad \"SH4\" mirrors pad \"SH3\" across y     # SH3 (the prototype) takes the −x side\n  span pad \"SH3\" to pad \"SH4\" is 8.0       # outer edge to outer edge\n  pad \"SH3\" is 0.9 above pad \"SH1\"\n\n  pads \"SH1\", \"SH2\", \"SH3\", \"SH4\" { mask +0.1 }\n\n  # --- body, dimensioned from the shield group --------------------------\n  group shield = pad \"SH1\", pad \"SH2\", pad \"SH3\", pad \"SH4\"\n  body 7.6 x 5.0 x 2.45\n  body is centered on group shield horizontally\n  body top is 0.5 above hole PEG1\n\n  # --- graphics and 3D --------------------------------------------------\n  silk {\n    line (-4.1, -2.6) (-4.1, -1.2) width 0.12    # flag the mating-face corners\n    line (4.1, -2.6) (4.1, -1.2) width 0.12\n  }\n  courtyard auto 0.5\n\n  model {\n    step \"models/usb_microb.step\" offset (0, 0, 0) rotate (0, 0, -90) scale 1.0\n  }\n}\n"
